import java.io.*;
import java.math.BigInteger;

public class Main {
    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(new String(System.in.readAllBytes()).trim());
        BigInteger mod = BigInteger.valueOf(1000000007L);
        // First outer pair: 6 ordered choices; every inner pair: 3.
        BigInteger r = BigInteger.valueOf(3).modPow(BigInteger.valueOf(n / 2 - 1), mod);
        System.out.println(r.multiply(BigInteger.valueOf(6)).mod(mod));
    }
}

package main

import "fmt"

func main() {
	const MOD = 1000000007
	var n int64
	fmt.Scan(&n)
	// First outer pair: 6 ordered choices; every inner pair: 3.
	r, b := int64(6), int64(3)
	for e := n/2 - 1; e > 0; e >>= 1 {
		if e&1 == 1 {
			r = r * b % MOD
		}
		b = b * b % MOD
	}
	fmt.Println(r)
}
